# --- import-time premises (re-derived, never transcribed) ------------
# The same Tetens-liquid constants gpuwm.verify.sase_ref.moist_n2 uses.
_P0 = 100000.0
_RD, _CP, _XLV, _G = 287.0, 1004.5, 2.5e6, 9.81
_SVP1, _SVP2, _SVP3, _SVPT0 = 0.6112, 17.67, 29.65, 273.15
_EP2 = 0.6217504

TAGS = ("CAPSEARCH", "CAPLID", "KLID", "RH100", "LLES", "M1BDECK",
        "LOWRUN", "ROOTBND")


def _col(tag, name):
    return globals()[tag + "_" + name]


def _sat(th, qv, qc, p):
    """(qs, membership on the registered qt >= qs test, theta_es)."""
    t = th * (p / _P0) ** (_RD / _CP)
    es = 1000.0 * _SVP1 * np.exp(_SVP2 * (t - _SVPT0) / (t - _SVP3))
    qs = _EP2 * es / (p - es)
    return qs, (qv + qc) >= qs, th * np.exp(_XLV * qs / (_CP * t))


def _runs(memb, min_cells=2):
    """Every contiguous member run of at least ``min_cells`` cells."""
    out, k = [], 0
    while k < len(memb):
        if not memb[k]:
            k += 1
            continue
        s = k
        while k + 1 < len(memb) and memb[k + 1]:
            k += 1
        if k - s >= min_cells - 1:
            out.append((s, k))
        k += 1
    return out


def _peaks(thes):
    return [k for k in range(1, len(thes) - 1)
            if thes[k] > thes[k - 1] and thes[k] > thes[k + 1]]


def _geometry(tag):
    thick = _col(tag, "THICK")
    return thick, np.cumsum(thick) - 0.5 * thick, np.concatenate(
        ([0.0], np.cumsum(thick)))


for _t in TAGS:
    for _n in ("THETA", "QV", "QC", "P", "THICK", "E_FRAME"):
        assert len(_col(_t, _n)) == N_LEVELS, (_t, _n)
    # the registered survey standard: the frame's own turbulence is
    # below the G-M5 floor, which is why SURVEY_E and not *_E_FRAME
    # sets every amplitude here.
    assert _col(_t, "E_FRAME").max() < 0.5, _t
assert len(LLES_U) == N_LEVELS and len(LLES_V) == N_LEVELS

# CAPSEARCH / CAPLID: a qualifying run exists, it is NOT surface-based,
# k_lid is well inside the column -- so none of the OTHER three
# registered stand-down conditions can be what silences these columns --
# and the lid sits beyond VENT_DEPTH_CAP = 4000 m above the root.
for _t, _run, _kr, _depth in (("CAPSEARCH", (15, 27), 11, 4000.0),
                              ("CAPLID", (9, 23), 9, 4000.0)):
    _qs, _m, _thes = _sat(_col(_t, "THETA"), _col(_t, "QV"),
                          _col(_t, "QC"), _col(_t, "P"))
    _rr = _runs(_m)
    assert _rr and _rr[0] == _run, (_t, _rr)
    _kb, _kt = _run
    assert _kb > 0, _t                      # not the surface stand-down
    assert _thes[_kt] < _thes[_kb], _t      # moist-unstable, so chosen
    assert _kt + 2 < N_LEVELS, _t           # k_lid inside the column
    _th, _zc, _zf = _geometry(_t)
    assert (_zc[_kt + 2] - _zc[_kr]) > _depth, (
        _t, _zc[_kt + 2] - _zc[_kr])

# KLID: the run's top is k15, so the entrainment zone is k16 and the C9
# hard-zero boundary k_lid = 17 -- and there are 32 levels above it, so
# the perturbation leg has a real cap to perturb.
_qs, _m, _thes = _sat(KLID_THETA, KLID_QV, KLID_QC, KLID_P)
assert _runs(_m)[0] == (13, 15), _runs(_m)
assert _thes[15] < _thes[13]
assert 15 + 2 < N_LEVELS - 1

# RH100: cell k16 carries qc EXACTLY zero at RH >= 100%, so the RH100
# limb of the switch is the ONLY term that can call it saturated.
_qs, _m, _thes = _sat(RH100_THETA, RH100_QV, RH100_QC, RH100_P)
assert RH100_QC[16] == 0.0, RH100_QC[16]
assert RH100_QV[16] >= _qs[16], (RH100_QV[16], _qs[16])
assert RH100_QV[16] / _qs[16] > 1.0
assert _runs(_m)[0] == (5, 16), _runs(_m)   # k16 IS the run's own top
# ... and it is what makes that run moist-unstable: drop it and the
# registered bulk reading flips sign, so no run qualifies at all.
assert _thes[16] - _thes[5] < 0.0 < _thes[15] - _thes[5]

# LLES: the column has saturated cells (so n2_eff departs from the dry
# field at all) and a resolved wind with real vertical shear (so the
# split step's momentum row can see the length at all).
_qs, _m, _thes = _sat(LLES_THETA, LLES_QV, LLES_QC, LLES_P)
assert _m.sum() >= 5, _m.sum()
assert np.abs(np.diff(LLES_U)).max() > 1.0

# M1BDECK: k16..k22 are saturated on MOIST_STABILITY_SWITCH's own
# reading (qc > 0 or qv >= qs -- the M1 switch, which is what gates the
# substitution mask M1b rides; the M2 membership test qt >= qs is a
# different, stricter reading and is not what this column is about), and
# the cell above the deck is not -- the lid.  Moist instability and dry
# stability are asserted in the test itself, from the authority's own
# N^2 fields rather than from this module's transcription.
_qs, _m, _thes = _sat(M1BDECK_THETA, M1BDECK_QV, M1BDECK_QC, M1BDECK_P)
_m1 = (M1BDECK_QC > 0.0) | (M1BDECK_QV >= _qs)
assert bool(np.all(_m1[16:23])), np.nonzero(~_m1[16:23])[0]
assert not bool(_m1[23])

# LOWRUN: TWO qualifying runs, both moist-unstable on the registered
# bulk theta_es reading -- the premise the lowest-run rule decides.
_qs, _m, _thes = _sat(LOWRUN_THETA, LOWRUN_QV, LOWRUN_QC, LOWRUN_P)
_rr = _runs(_m)
assert _rr == [(8, 11), (13, 15)], _rr
for _s, _e in _rr:
    assert _thes[_e] - _thes[_s] < 0.0, (_s, _e)

# ROOTBND: interior theta_es maxima at k7 AND at k11 = the run's own
# base, both at or above the structural depth floor -- so the ONLY rule
# that selects between them is the k <= k_base bound.
_qs, _m, _thes = _sat(ROOTBND_THETA, ROOTBND_QV, ROOTBND_QC, ROOTBND_P)
assert _runs(_m)[0] == (11, 15), _runs(_m)
assert _thes[15] < _thes[11]
_pk = [k for k in _peaks(_thes) if k <= 11]
assert _pk == [7, 11], _pk
assert min(_pk) >= 11 - (15 - 11) - 1              # the depth floor
